pe CONTRACT_DOCUMENT_TYPE, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'FIN.CREDIT_METHOD' and scv.value = lc.document_type) as document_type_desc, (SELECT sum(lcr.PLANNED_DUE_AMOUNT) FROM lon_contract_repayment lcr WHERE lcr.cf_item IN (303) and lcr.WITHDRAW_ID = lcw.withdraw_id and lcr.CONTRACT_ID = lc.contract_id) charge_amount_sum, (SELECT sum(lcr.PLANNED_DUE_AMOUNT) FROM lon_contract_repayment lcr WHERE lcr.cf_item IN (303) and lcr.WITHDRAW_ID = lcw.withdraw_id and lcr.CONTRACT_ID = lc.contract_id) / lcw.DUE_AMOUNT as lease_amount_proportion FROM lon_contract_withdraw lcw LEFT JOIN lon_contract lc ON lcw.contract_id = lc.contract_id LEFT JOIN lon_contract_quotation lcq ON lcw.withdraw_id = lcq.withdraw_id
