.WITHDRAW_ID = lcw.withdraw_id and lcr.CONTRACT_ID = lc.contract_id) / lcw.DUE_AMOUNT as lease_amount_proportion FROM lon_contract_withdraw lcw LEFT JOIN lon_contract lc ON lcw.contract_id = lc.contract_id left join lon_contract_quotation lcq on lcw.withdraw_id = lcq.withdraw_id where lcw.data_class= 'NORMAL' ) tmp
