SELECT (lc.loan_term)*( CASE lc.loan_term_uom WHEN 'DAY' THEN 1/30 WHEN 'MONTH' THEN 1 ELSE 12 END ) as loan_term, sum(lcw.due_amount) as due_amount, (sum(lcw.due_amount)/( SELECT sum(lcw.due_amount) as due_amount
FROM lon_contract_withdraw lcw RIGHT JOIN lon_contract lc on lcw.contract_id=lc.contract_id WHERE lcw.withdraw_status = 'APPROVED' and lc.loan_term is not NULL and lc.loan_term_uom is not null)*100) as partPercent
FROM lon_contract_withdraw lcw RIGHT JOIN lon_contract lc on lcw.contract_id=lc.contract_id WHERE lcw.withdraw_status = 'APPROVED' and lc.loan_term is not NULL and lc.loan_term_uom is not null GROUP BY (lc.loan_term)*( CASE lc.loan_term_uom WHEN 'DAY' THEN 1/30 WHEN 'MONTH' THEN 1 ELSE 12 END )
