(SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE scvb.CODE_ID=(
SELECT scb.CODE_ID FROM sys_code_b scb WHERE scb.CODE='HLS_WFL_STATUS'
) AND scvb.VALUE= t.withdraw_status) as withdraw_status_n
from lon_contract_withdraw t

    t.contract_id = #{contractId}

        and t.withdraw_id = #{withdrawId}


        and t.withdraw_status = #{status}

select  *  from  lon_contract_withdraw  tt

    1=1

        and tt.change_req_id = #{changeReqId}
